/* Container: centred column with side padding. */
.container { width: 100%; margin-inline: auto; padding-inline: var(--s5); }
.container-text { max-width: calc(var(--measure) + 2 * var(--s5)); }
.container-page { max-width: calc(var(--content) + 2 * var(--s5)); }
.container-full { max-width: none; }

.heading { font-weight: 500; line-height: 1.15; text-wrap: balance; }
.heading-display { font-family: var(--font-display); font-weight: 700; font-size: var(--display-md); letter-spacing: -0.035em; line-height: 0.95; }
.heading-xl { font-family: var(--font-display); font-weight: 700; font-size: var(--display-sm); letter-spacing: -0.03em; }
.heading-lg { font-size: calc(var(--text-lg) * 1.35); }
.heading.heading-md { font-size: var(--text-lg); } /* two classes: typography.css (later in the bundle) also defines .heading-md and .heading-sm with other sizes */
.heading.heading-sm { font-size: var(--text-base); }

/* Block: testimonials. */
.block-testimonials { padding-block: var(--s8); }
.block-testimonials-title { margin-bottom: var(--s6); }
.block-testimonials-grid { display: grid; gap: var(--s5); grid-template-columns: 1fr; }
.block-testimonial { margin: 0; display: flex; flex-direction: column; justify-content: space-between; gap: var(--s5); padding: var(--s5); border: 1px solid var(--rule); min-width: 0; }
.block-testimonial blockquote { margin: 0; font-size: var(--text-lg); line-height: 1.4; }
.block-testimonial figcaption { display: flex; align-items: center; gap: var(--s3); font-size: var(--text-sm); }
.block-testimonial figcaption > span:last-child { display: flex; flex-direction: column; }
.block-testimonial-avatar { display: inline-flex; }
.block-testimonial-name { font-weight: 500; }
.block-testimonial-role { color: var(--muted); }
@media (min-width: 760px) { .block-testimonials-grid { grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); } }

usage:
import {BlockTestimonials} from '@monoline/react';

<BlockTestimonials
  title="What people say"
  items={[
    {quote: 'It stayed out of the way and the pages got simpler.', name: 'Ada Example', role: 'Engineer, Example Co'},
    {quote: 'Keyboard support worked on day one.', name: 'Sam Sample', role: 'Designer, Sample Studio'},
    {quote: 'We deleted a lot of CSS.', name: 'Robin Placeholder', role: 'Founder, Placeholder'},
  ]}
/>

